public class BookRefTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String titlesOf(java.util.List<BookRef> books) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < books.size(); i++) {
            if (i > 0) {
                sb.append(",");
            }
            sb.append(books.get(i).title());
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        BookRef emma = new BookRef("Emma", 1815);
        BookRef ulysses = new BookRef("Ulysses", 1922);
        BookRef hobbit = new BookRef("The Hobbit", 1937);
        BookRef dune = new BookRef("Dune", 1965);
        BookRef carrie = new BookRef("Carrie", 1974);
        BookRef jaws = new BookRef("Jaws", 1974);
        BookRef beloved = new BookRef("Beloved", 1987);

        java.util.List<BookRef> shelf = new java.util.ArrayList<>(
                java.util.List.of(dune, beloved, jaws, emma, hobbit, carrie, ulysses));
        java.util.Collections.sort(shelf);
        check("sorted shelf order",
                "Emma,Ulysses,The Hobbit,Dune,Carrie,Jaws,Beloved", titlesOf(shelf));

        check("earlier year compares negative", -1, Integer.signum(emma.compareTo(ulysses)));
        check("later year compares positive", 1, Integer.signum(beloved.compareTo(dune)));
        check("same year falls back to title", -1, Integer.signum(carrie.compareTo(jaws)));
        check("same year, reversed order", 1, Integer.signum(jaws.compareTo(carrie)));
        check("identical book compares as 0", 0, new BookRef("Dune", 1965).compareTo(dune));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

