public record BookRef(String title, int year) implements Comparable<BookRef> {

    @Override
    public int compareTo(BookRef other) {
        int byYear = Integer.compare(year, other.year);
        if (byYear != 0) {
            return byYear;
        }
        return title.compareTo(other.title);
    }
}
